      {
        "description": "Instructor physical attractiveness (average rating from 6 judges, centered at sample mean). Modeled as the primary independent variable with both linear and quadratic terms to allow nonlinearity.",
        "columns": [
          "beauty",
          "beauty_sq"
        ]
      }
    ],
    "dv": {
      "description": "Course overall teaching evaluation score (student instructional rating), continuous outcome (1-5).",
      "columns": [
        "eval"
      ]
    },
    "controls": [
      {
        "description": "Instructor gender coded as 1 if female, 0 if male. Included both as a main control and as a moderator (interaction with beauty) to test whether the beauty effect differs by gender.",
        "is_moderator": true,
        "moderator_on": "beauty",
        "columns": [
          "female"
        ]
      },
      {
        "description": "Instructor age in years (continuous).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "age"
        ]
      },
      {
        "description": "Log of the number of students who participated in the evaluation (continuous). Uses natural log to reduce skew.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "log_students"
        ]
      },
