      },
      {
        "description": "Course division (categorical: 'lower' or 'upper'). Controls for course level differences.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "division"
        ]
      },
      {
        "description": "Course credit type (categorical: 'single' credit elective vs 'more').",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "credits"
