stype(int)\n\n    # Final: keep only columns needed for modeling to avoid accidental usage of others\n    keep_cols = [\n        'Eval', 'beauty_std', 'IsFemale', 'IsMinority', 'IsTenure', 'IsNative',\n        'IsSingleCredit', 'IsUpperDivision', 'Age_z', 'Students_z', 'prof'\n    ]\n    df = df.loc[:, keep_cols]\n\n    return df\n",
